import{_ as a,o as t,c as e,a2 as i}from"./chunks/framework.Lq8Lraw_.js";const g=JSON.parse('{"title":"24 .gitattributes 与合并策略","description":"","frontmatter":{},"headers":[],"relativePath":"guide/mastery/05-gitattributes.md","filePath":"guide/mastery/05-gitattributes.md","lastUpdated":1792671989000}'),n={name:"guide/mastery/05-gitattributes.md"};function d(o,s,l,p,r,c){return t(),e("div",null,[...s[0]||(s[0]=[i(`<h1 id="_24-gitattributes-与合并策略" tabindex="-1">24 .gitattributes 与合并策略 <a class="header-anchor" href="#_24-gitattributes-与合并策略" aria-label="Permalink to &quot;24 .gitattributes 与合并策略&quot;">​</a></h1><p><code>.gitignore</code> 决定哪些文件不进仓库，<code>.gitattributes</code> 决定进仓库的文件如何被处理：换行怎么转换、二进制如何 diff、冲突能否自动合并、归档时排除什么。它随仓库提交，对所有人和 CI 生效，是跨平台团队最容易忽略的一份配置。</p><h2 id="学习目标" tabindex="-1">学习目标 <a class="header-anchor" href="#学习目标" aria-label="Permalink to &quot;学习目标&quot;">​</a></h2><ul><li>理解跨平台换行、二进制文件和语言统计为什么需要仓库级统一。</li><li>掌握 <code>text=auto</code>、<code>eol=lf</code>、<code>binary</code>、<code>-diff</code> 的语义与生效顺序。</li><li>能为特定文件配置 diff 驱动与 <code>merge=ours</code> / <code>merge=union</code> / <code>-merge</code>。</li><li>能用 <code>export-ignore</code>、<code>linguist-generated</code> 控制归档与统计，并用 <code>git check-attr</code> 排查生效情况。</li></ul><h2 id="为什么需要它" tabindex="-1">为什么需要它 <a class="header-anchor" href="#为什么需要它" aria-label="Permalink to &quot;为什么需要它&quot;">​</a></h2><table tabindex="0"><thead><tr><th>问题</th><th>没有配置的后果</th><th>对应属性</th></tr></thead><tbody><tr><td>Windows 提交 CRLF</td><td>diff 全文件变更、CI 脚本因 <code>\\r</code> 失败</td><td><code>text=auto</code>、<code>eol=lf</code></td></tr><tr><td>图片/字体被当文本</td><td>仓库膨胀、合并产生乱码冲突</td><td><code>binary</code></td></tr><tr><td>生成代码计入统计</td><td>语言占比、覆盖率失真</td><td><code>linguist-generated</code></td></tr><tr><td>发布包带测试文档</td><td>制品体积变大</td><td><code>export-ignore</code></td></tr></tbody></table><p>这些规则必须写在仓库里，而不是各人的 <code>core.autocrlf</code> 里：本地配置约束不了同事，也约束不了 CI。</p><h2 id="基本语法与生效顺序" tabindex="-1">基本语法与生效顺序 <a class="header-anchor" href="#基本语法与生效顺序" aria-label="Permalink to &quot;基本语法与生效顺序&quot;">​</a></h2><p>每行是 <code>pattern attr1 attr2=value ...</code>，通配符规则与 <code>.gitignore</code> 相同：</p><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span># 默认自动判断文本/二进制，文本按 LF 存储</span></span>
<span class="line"><span>* text=auto</span></span>
<span class="line"><span></span></span>
<span class="line"><span># 明确文本文件，检出时统一换行</span></span>
<span class="line"><span>*.js  text eol=lf</span></span>
<span class="line"><span>*.sh  text eol=lf</span></span>
<span class="line"><span>*.bat text eol=crlf</span></span>
<span class="line"><span></span></span>
<span class="line"><span># 二进制：不转换换行，不生成文本 diff</span></span>
<span class="line"><span>*.png   binary</span></span>
<span class="line"><span>*.woff2 binary</span></span>
<span class="line"><span></span></span>
<span class="line"><span># 不希望在 diff 中展开</span></span>
<span class="line"><span>package-lock.json -diff</span></span>
<span class="line"><span>*.min.js -diff</span></span>
<span class="line"><span></span></span>
<span class="line"><span># 生成代码与第三方代码：折叠 diff、排除统计</span></span>
<span class="line"><span>dist/**   linguist-generated=true</span></span>
<span class="line"><span>vendor/** linguist-vendored=true</span></span></code></pre></div><p><strong>同一属性被多次匹配时，后写的规则覆盖前面的</strong>，所以 <code>* text=auto</code> 放最前，例外放后面。常用属性：</p><table tabindex="0"><thead><tr><th>写法</th><th>含义</th></tr></thead><tbody><tr><td><code>text</code></td><td>标记文本，提交时统一转 LF</td></tr><tr><td><code>text=auto</code></td><td>Git 自行判断，判为文本才规范化</td></tr><tr><td><code>-text</code></td><td>强制按二进制处理，禁止换行转换</td></tr><tr><td><code>eol=lf</code> / <code>eol=crlf</code></td><td>检出到工作区使用的换行（需配合 <code>text</code>）</td></tr><tr><td><code>binary</code></td><td>等价于 <code>-text -diff -merge</code></td></tr><tr><td><code>-diff</code></td><td>不生成文本 diff，显示 Binary files differ</td></tr><tr><td><code>-merge</code></td><td>禁止自动合并，冲突时整文件交给人工</td></tr><tr><td><code>merge=union</code></td><td>冲突块保留双方内容并拼接</td></tr></tbody></table><div class="warning custom-block"><p class="custom-block-title">属性只影响之后的文件</p><p>修改 <code>.gitattributes</code> 不会重写已入库文件的换行，必须执行 <code>git add --renormalize .</code> 并提交，否则会长期残留 LF/CRLF 混合状态。</p></div><h2 id="换行策略-text-auto-与-eol-lf" tabindex="-1">换行策略：text=auto 与 eol=lf <a class="header-anchor" href="#换行策略-text-auto-与-eol-lf" aria-label="Permalink to &quot;换行策略：text=auto 与 eol=lf&quot;">​</a></h2><p>推荐在 <code>* text=auto</code> 基础上，再给脚本显式加 <code>eol=lf</code>、给 <code>.bat</code> 加 <code>eol=crlf</code>。提交时统一转 LF，检出时按 <code>eol</code> 决定，未指定则遵循 <code>core.eol</code> / <code>core.autocrlf</code>。</p><p>建议关闭个人转换，交给仓库属性统一：</p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">git</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> config</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --global</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> core.autocrlf</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> false</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">git</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> config</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --global</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> core.safecrlf</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> warn</span><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;">   # 转换不可逆时警告</span></span></code></pre></div><div class="tip custom-block"><p class="custom-block-title">检查仓库实际存了什么</p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">git</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> ls-files</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --eol</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> src/</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;"> |</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;"> head</span></span>
<span class="line"><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;"># i/lf w/crlf attr/text=auto  src/win.bat</span></span>
<span class="line"><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;"># i/lf w/lf   attr/text=auto  src/app.ts</span></span></code></pre></div><p><code>i/</code> 是索引，<code>w/</code> 是工作区，<code>attr/</code> 是最终生效属性。排查换行问题比反复 diff 更快。</p></div><h2 id="二进制与-diff-驱动" tabindex="-1">二进制与 diff 驱动 <a class="header-anchor" href="#二进制与-diff-驱动" aria-label="Permalink to &quot;二进制与 diff 驱动&quot;">​</a></h2><p><code>binary</code> 覆盖大多数场景；需要保留文本 diff 能力时，声明驱动并配置：</p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;"># 对应 .gitattributes 中的 *.sql diff=sql</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">git</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> config</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> diff.sql.textconv</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> cat</span></span></code></pre></div><p>对加密文件、压缩包、锁文件使用 <code>-diff</code>，避免 review 时展开无意义内容。</p><h2 id="合并策略-ours、union-与-merge" tabindex="-1">合并策略：ours、union 与 -merge <a class="header-anchor" href="#合并策略-ours、union-与-merge" aria-label="Permalink to &quot;合并策略：ours、union 与 -merge&quot;">​</a></h2><p>配置分两步：<code>.gitattributes</code> 声明策略名，<code>git config</code> 定义驱动实现。</p><h3 id="merge-ours-冲突时保留当前分支" tabindex="-1">merge=ours：冲突时保留当前分支 <a class="header-anchor" href="#merge-ours-冲突时保留当前分支" aria-label="Permalink to &quot;merge=ours：冲突时保留当前分支&quot;">​</a></h3><p>用于自动生成、每个分支各自维护的锁文件或版本文件：</p><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>package-lock.json merge=ours</span></span>
<span class="line"><span>version.json      merge=ours</span></span></code></pre></div><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">git</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> config</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> merge.ours.driver</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> true</span><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;">    # 必须配置，否则策略不存在</span></span></code></pre></div><p><strong>风险</strong>：它会静默选择 ours，包括真正需要合并的依赖升级。某分支新增依赖、锁文件却没变，CI 可能因 <code>package-lock.json</code> 与 <code>package.json</code> 不一致而失败。只对「可重新生成且 CI 会校验一致性」的文件使用。</p><h3 id="merge-union-保留双方内容" tabindex="-1">merge=union：保留双方内容 <a class="header-anchor" href="#merge-union-保留双方内容" aria-label="Permalink to &quot;merge=union：保留双方内容&quot;">​</a></h3><p>适合追加型文本：变更日志、<code>.gitignore</code>、并列的国际化词条。</p><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>CHANGELOG.md merge=union</span></span>
<span class="line"><span>.gitignore   merge=union</span></span></code></pre></div><p><strong>风险</strong>：union 只保证不出现冲突标记，不保证结果合法。同一位置各加一行依赖可能重复声明；用于代码文件会直接产生语法错误。</p><h3 id="merge-禁止自动合并" tabindex="-1">-merge：禁止自动合并 <a class="header-anchor" href="#merge-禁止自动合并" aria-label="Permalink to &quot;-merge：禁止自动合并&quot;">​</a></h3><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>*.pdf  -merge</span></span>
<span class="line"><span>*.xlsx -merge</span></span></code></pre></div><p>双方都修改时，Git 会明确报冲突（<code>CONFLICT (binary)</code> 或 <code>CONFLICT (content)</code>），保留当前分支版本，由人决定取舍。它不会逐行拼接，因此不会产出半截损坏的文件。</p><div class="danger custom-block"><p class="custom-block-title">merge=ours 不是万能冲突消除器</p><p>它只对声明了该属性的文件生效，且会掩盖依赖/版本变化。不要给源码、数据库迁移脚本配置 <code>merge=ours</code>；迁移冲突必须在合并时人工排序，否则生产环境会漏执行。</p></div><h2 id="归档与语言统计" tabindex="-1">归档与语言统计 <a class="header-anchor" href="#归档与语言统计" aria-label="Permalink to &quot;归档与语言统计&quot;">​</a></h2><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span># git archive 生成的发布包中排除开发文件</span></span>
<span class="line"><span>tests/** export-ignore</span></span>
<span class="line"><span></span></span>
<span class="line"><span># GitHub 语言统计与 diff 折叠</span></span>
<span class="line"><span>dist/**        linguist-generated=true</span></span>
<span class="line"><span>third_party/** linguist-vendored=true</span></span></code></pre></div><p><code>export-ignore</code> 只影响 <code>git archive</code>，不影响 <code>clone</code>；<code>linguist-*</code> 只被 GitHub 等平台识别，Git 本身不关心。</p><h2 id="排查-属性生效了吗" tabindex="-1">排查：属性生效了吗 <a class="header-anchor" href="#排查-属性生效了吗" aria-label="Permalink to &quot;排查：属性生效了吗&quot;">​</a></h2><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">git</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> check-attr</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> text</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> eol</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> merge</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> diff</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> src/app.ts</span></span>
<span class="line"><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;"># src/app.ts: text: auto</span></span>
<span class="line"><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;"># src/app.ts: eol: lf</span></span>
<span class="line"></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">git</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> check-attr</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -a</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> package-lock.json</span><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;">    # 查看全部属性</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">git</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> ls-files</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --eol</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> src/app.ts</span><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;">          # 索引与工作区换行</span></span></code></pre></div><p>常见「不生效」原因：</p><table tabindex="0"><thead><tr><th>现象</th><th>原因</th></tr></thead><tbody><tr><td>新克隆换行仍混乱</td><td>旧文件未执行 <code>add --renormalize</code></td></tr><tr><td><code>merge=ours</code> 报未知驱动</td><td>缺少 <code>merge.ours.driver</code></td></tr><tr><td>规则写了却没匹配</td><td>路径层级或大小写错误，<code>*</code> 不跨 <code>/</code></td></tr><tr><td>例外规则失效</td><td>后写规则优先，顺序放反</td></tr><tr><td>只在本地生效</td><td>属性文件未提交，只改了 <code>core.autocrlf</code></td></tr></tbody></table><p>一次性重新规范化：</p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">git</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> add</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --renormalize</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> .</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">git</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> commit</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -m</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> &quot;chore: 按 .gitattributes 重新规范化换行&quot;</span></span></code></pre></div><h2 id="常见坑" tabindex="-1">常见坑 <a class="header-anchor" href="#常见坑" aria-label="Permalink to &quot;常见坑&quot;">​</a></h2><table tabindex="0"><thead><tr><th>坑</th><th>后果</th><th>建议</th></tr></thead><tbody><tr><td>只配 <code>core.autocrlf</code></td><td>每人行为不一致</td><td>仓库内统一 <code>* text=auto</code></td></tr><tr><td>给源码配 <code>merge=ours</code></td><td>静默丢弃对方修改</td><td>只用于可再生成产物</td></tr><tr><td>给代码配 <code>merge=union</code></td><td>重复声明、语法错误</td><td>只用于追加型文本</td></tr><tr><td>二进制未标记</td><td>仓库膨胀、合并损坏</td><td><code>binary</code> 或 <code>-merge</code></td></tr><tr><td>改属性后不 renormalize</td><td>换行问题残留</td><td><code>git add --renormalize .</code></td></tr><tr><td>以为 <code>export-ignore</code> 能瘦身 clone</td><td>只影响 archive</td><td>瘦身用 LFS 或拆仓库</td></tr></tbody></table><h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><ul><li><code>.gitattributes</code> 把文件处理方式变成仓库级契约，优先级高于个人配置。</li><li>换行用 <code>* text=auto</code> 打底、脚本用 <code>eol=lf</code>，改完必须重新规范化。</li><li><code>binary</code> / <code>-diff</code> 处理二进制与噪音文件；<code>merge=ours</code> 只适合可再生成产物，<code>merge=union</code> 只适合追加型文本，<code>-merge</code> 用于必须人工处理的文件。</li><li><code>export-ignore</code> 与 <code>linguist-*</code> 控制归档和统计；排查顺序：<code>git check-attr</code> → <code>git ls-files --eol</code> → 属性文件是否已提交。</li></ul><p>规范化流程可以交给钩子自动执行，见 <a href="/git-tutorial-site/guide/mastery/04-hooks">hooks：团队规范自动化</a>；换行报错处理见 <a href="/git-tutorial-site/guide/appendix/02-faq">报错 FAQ</a>。</p>`,51)])])}const k=a(n,[["render",d]]);export{g as __pageData,k as default};
